using System;
using System.Diagnostics;

// PROGRAM: Mengamati Efek Tiered Compilation dan JIT Warm-Up
static long HitungKalkulasi(int batas)
{
    long total = 0;
    for (int i = 0; i < batas; i++)
    {
        total += (i ^ 3);
    }
    return total;
}

Console.WriteLine("=== EKSPERIMEN JIT TIERING & WARM-UP ===");

// 1. Eksekusi Pertama: Memicu Kompilasi JIT Tier 0 (Cold Start)
var sw1 = Stopwatch.StartNew();
HitungKalkulasi(100_000);
sw1.Stop();
Console.WriteLine($"Panggilan 1 (Cold JIT Compilation) : {sw1.ElapsedTicks} ticks ({sw1.ElapsedMilliseconds} ms)");

// 2. Eksekusi Berulang untuk memicu promosi ke Tier 1 Full Optimization
for (int i = 0; i < 50; i++)
{
    HitungKalkulasi(100_000);
}

// 3. Eksekusi Setelah Teroptimasi (Warm State)
var sw2 = Stopwatch.StartNew();
HitungKalkulasi(100_000);
sw2.Stop();
Console.WriteLine($"Panggilan 52 (Hot JIT Steady-State) : {sw2.ElapsedTicks} ticks ({sw2.ElapsedMilliseconds} ms)");

Console.WriteLine($"\nPercepatan Eksekusi: {sw1.ElapsedTicks / Math.Max(1, sw2.ElapsedTicks)}x lebih efisien!");

