using System;

public class JitTierInspector
{
    public static string GetJitOptimizationTier(int callCount) => callCount switch
    {
        <= 0 => "Uncompiled",
        1 => "Tier0-QuickJIT",
        < 30 => "Tier0-Profiling",
        _ => "Tier1-FullOpt-PGO"
    };

    public static void Main()
    {
        Console.WriteLine(GetJitOptimizationTier(1));
        Console.WriteLine(GetJitOptimizationTier(15));
        Console.WriteLine(GetJitOptimizationTier(50));
    }
}
